"""Curate the accepted local 1512 grasp repair and its existing receipts."""
import json,hashlib
from pathlib import Path
from datetime import datetime,timezone
P=Path(__file__).resolve().parent
ROOT=P.parents[4]
def read(name):return json.loads((P/name).read_text())
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def write(name,data):(P/name).write_text(json.dumps(data,indent=2)+'\n')
source_sha=sha(P/'source.blend');glb_sha=sha(P/'motion.glb')
catalogue_path=ROOT/'catalogue/exercises/1512.json';catalogue=json.loads(catalogue_path.read_text())
context_path=P.parents[1]/'contexts/1512.json';context=json.loads(context_path.read_text())
adapter_path=ROOT/'artifacts/exercise-batches/dual-quaternion.js'
