decoded=read('decoded-physical-report.json');cross=read('decoded-triangle-contact-report.json');export=read('export-verification.json')
source=read('source-verification.json');weight=read('weight-readback.json');game=read('asset-qa.json');limb=read('limb-integrity-report.json')
for receipt in [surface,grasp,native,decoded,cross,export,source,weight,game,limb,read('early-render-readback.json'),read('camera-framing-report.json')]:
 assert receipt['source_sha256']==source_sha
for receipt in [decoded,cross]:assert receipt['glb_sha256']==glb_sha
assert export['sha256']==glb_sha and cross['adapter_sha256']==adapter['sha256']
assert surface['ok'] and decoded['pass'] and cross['pass'] and export['ok'] and game['pass'] and source['pass'] and limb['pass']
