clip=read('clip.json')
write('authoring-context.json',{'exercise_id':'1512','catalogue_sha256':sha(catalogue_path),'catalogue_snapshot':catalogue,'context_sha256':sha(context_path),'context_snapshot':context,'source_cue_resolution':resolution,'owned_path':str(P.relative_to(ROOT)),'source_frames':'Native 1..151 map to runtime 0..150 at 30 fps.','restricted_media_used':False,'history_status':'Previous batch-005 motion is user-rejected; only explicitly recorded body components are reused.'})
