contact_stages=[]
for f in [0,25,32,36,39,40,60,75,90,111,115,118,140,150]:
 row=grasp['samples'][f];contact_stages.append({'frame':f,'time_seconds':f/30,'wrist_deviation_degrees':native['samples'][f]['wrist_deviation_degrees'],'parts':row['parts']})
write('grasp-trajectory-report.json',{'source_sha256':source_sha,'frames':151,'contact_frame':'LeftFoot native bone frame, fixed hand matrix from acquisition through pull/hold/unload, runtime frames 39..111.','foot_local_grasp_matrix':native['foot_local_grasp_matrix'],'palm_source_id':native['palm_source_id'],'palm_source_coordinate':native['palm_source_coordinate'],'foot_anchor_source_coordinate':native['foot_anchor_source_coordinate'],'foot_anchor_source_normal':native['foot_anchor_source_normal'],'held_matrix_maximum_error':grasp['held_foot_local_hand_matrix_maximum_error'],'active_airborne_wrist_deviation_max_degrees':grasp['active_airborne_wrist_deviation_max_degrees'],'planted_wrist_note':'Floor planting and replanting deliberately use wrist extension; active-airborne maximum excludes those transitions. All151 wrist deviations remain in early-native-readback.json.','maximum_recorded_local_penetration_m':grasp['maximum_recorded_local_penetration_m'],'held_minimum_part_clearance_m':grasp['held_minimum_part_clearance_m'],'held_palm_minimum_clearance_m':grasp['held_palm_minimum_clearance_m'],'held_minimum_hand_vertices_within5mm':min(x['ankle_grip']['hand_vertices_within5mm']for x in held),'object_normal_angle_note':'Sampled object contact normals are descriptive, not a force-closure gate. Root accepted meaningful palm/thumb/index contact with remaining digits curved outside the corrected collar.','reach_comparison':grasp['reach_comparison'],'stages':contact_stages,'limits':'Nearest-normal signed distances are local diagnostics. Complete decoded triangle crossing results are separate; discrete samples do not certify continuous-time or enclosed-volume nonintersection.'})
warnings=read('qa-warning-locations.json')
